function DeleteProjectButton({ onDelete }: { onDelete: () => Promise<void> }) {
  const [isDeleting, setIsDeleting] = useState(false);

  const remove = async () => {
    setIsDeleting(true);
    try {
      await onDelete();
    } finally {
      setIsDeleting(false);
    }
  };

  return (
    <JxButton variant="danger" size="sm" disabled={isDeleting} onClick={remove}>
      Удалить
    </JxButton>
  );
}

function DueDate() {
  const [date, setDate] = useState<Date | null>(null);
  return <JxCalendar locale="ru-RU" value={date} onValueChange={setDate} />;
}

function TermsConsent() {
  const [agreed, setAgreed] = useState(false);
  return (
    <JxCheckbox
      label="Согласен с условиями обработки данных"
      checked={agreed}
      onChange={(event) => setAgreed(event.target.checked)}
    />
  );
}

const periods = [
  { value: 'week', label: 'Неделя' },
  { value: 'month', label: 'Месяц' },
  { value: 'year', label: 'Год' },
];

function PeriodChips() {
  const [selected, setSelected] = useState('month');
  return (
    <div style={{ display: 'flex', gap: '8px' }}>
      {periods.map((period) => (
        <JxChip key={period.value} active={period.value === selected} onClick={() => setSelected(period.value)}>
          {period.label}
        </JxChip>
      ))}
    </div>
  );
}

