function NavigationDrawer({ go, logout }: { go: (path: string) => void; logout: () => void }) {
  const [menuOpen, setMenuOpen] = useState(false);
  return (
    <>
      <JxButton variant="ghost" onClick={() => setMenuOpen(true)}>
        Разделы
      </JxButton>
      <JxDrawer open={menuOpen} onOpenChange={setMenuOpen} title="Разделы" side="left">
        <JxMenu
          items={[
            { label: 'Проекты', onSelect: () => go('/projects') },
            { label: 'Команда', onSelect: () => go('/team') },
            { type: 'divider' },
            { label: 'Выйти', danger: true, onSelect: logout },
          ]}
        />
      </JxDrawer>
    </>
  );
}

function EmailField() {
  const [email, setEmail] = useState('');
  const emailError = email.length > 0 && !email.includes('@') ? 'Укажите адрес с символом @' : undefined;
  return (
    <JxInputField
      label="Электронная почта"
      type="email"
      required
      value={email}
      onChange={(event) => setEmail(event.target.value)}
      errorText={emailError}
    />
  );
}

function ProjectActions({ rename, duplicate, remove }: { rename: () => void; duplicate: () => void; remove: () => void }) {
  return (
    <JxMenu
      items={[
        { type: 'label', label: 'Проект' },
        { label: 'Переименовать', shortcut: 'F2', onSelect: rename },
        { label: 'Дублировать', onSelect: duplicate },
        { type: 'divider' },
        { label: 'Удалить', danger: true, onSelect: remove },
      ]}
    />
