function DeleteProject({ removeProject }: { removeProject: () => void }) {
  const [confirmOpen, setConfirmOpen] = useState(false);
  return (
    <>
      <JxButton variant="danger" onClick={() => setConfirmOpen(true)}>
        Удалить проект
      </JxButton>
      <JxModal
        open={confirmOpen}
        onOpenChange={setConfirmOpen}
        intent="danger"
        title="Удалить проект?"
        message="Проект и все задачи будут удалены безвозвратно."
      >
        <JxButton variant="ghost" onClick={() => setConfirmOpen(false)}>
          Отмена
        </JxButton>
        <JxButton variant="danger" onClick={removeProject}>
          Удалить
        </JxButton>
      </JxModal>
    </>
  );
}

const pageSize = 10;

function PagedUsers({ users }: { users: Array<{ id: string; name: string }> }) {
  const [page, setPage] = useState(1);
  const pageCount = Math.ceil(users.length / pageSize);
  const visible = users.slice((page - 1) * pageSize, page * pageSize);
  return (
    <>
      <ul>
        {visible.map((user) => (
          <li key={user.id}>{user.name}</li>
        ))}
      </ul>
      <JxPagination total={pageCount} page={page} onPageChange={setPage} />
    </>
  );
}

function SignInPassword() {
  const [password, setPassword] = useState('');
  return (
    <JxPasswordField
      label="Пароль"
      required
      value={password}
      onChange={(event) => setPassword(event.target.value)}
      revealLabel="Показать пароль"
      hideLabel="Скрыть пароль"
