function NewPassword() {
  const [next, setNext] = useState('');
  const [repeat, setRepeat] = useState('');
  return (
    <>
      <JxPasswordField
        label="Новый пароль"
        autoComplete="new-password"
        helperText="Не короче 12 символов"
        value={next}
        onChange={(event) => setNext(event.target.value)}
      />
      <JxPasswordField
        label="Повторите пароль"
        autoComplete="new-password"
        value={repeat}
        onChange={(event) => setRepeat(event.target.value)}
        errorText={repeat && repeat !== next ? 'Пароли не совпадают' : undefined}
      />
    </>
  );
}

function UploadProgress({ uploaded, total }: { uploaded: number; total: number }) {
  return <JxProgress label="Загрузка" value={uploaded} max={total} />;
}

function PlanPicker() {
  const [plan, setPlan] = useState<'basic' | 'pro'>('basic');
  return (
    <div role="radiogroup" aria-label="Тариф">
      <JxRadio name="plan" value="basic" label="Базовый" checked={plan === 'basic'} onChange={() => setPlan('basic')} />
      <JxRadio name="plan" value="pro" label="Про" checked={plan === 'pro'} onChange={() => setPlan('pro')} />
    </div>
  );
}

function LanguageSelect() {
  const [language, setLanguage] = useState('ru');
  return (
    <JxSelect
      label="Язык"
      options={[
        { value: 'ru', label: 'Русский' },
        { value: 'en', label: 'English' },
      ]}
      value={language}
      onValueChange={setLanguage}
    />
  );
}

function CheckoutSteps() {
  const [step, setStep] = useState(0);
  return (
    <>
      <JxStepper steps={[{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }]} current={step} />
      <JxButton variant="ghost" disabled={step === 0} onClick={() => setStep(step - 1)}>
        Назад
      </JxButton>
      <JxButton variant="primary" onClick={() => setStep(Math.min(step + 1, 2))}>
        Дальше
      </JxButton>
    </>
  );
}

function EmailNotifications() {
  const [notifications, setNotifications] = useState(true);
  return (
    <JxSwitch
      label="Присылать уведомления на почту"
      checked={notifications}
      onChange={(event) => setNotifications(event.target.checked)}
    />
