}

interface User {
  id: string;
  name: string;
  role: string;
  active: boolean;
}

function UsersTable({ users }: { users: User[] }) {
  return (
    <JxTable>
      <thead>
        <tr>
          <th>Имя</th>
          <th>Роль</th>
          <th>Статус</th>
        </tr>
      </thead>
      <tbody>
        {users.map((user) => (
