function ProfileTabs({ general, security }: { general: ReactNode; security: ReactNode }) {
  const [tab, setTab] = useState('general');
  return (
    <>
      <JxTabs
        ariaLabel="Разделы профиля"
        items={[
          { value: 'general', label: 'Общее' },
          { value: 'security', label: 'Безопасность' },
        ]}
        value={tab}
